import numpy as np

def initialize(distances: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    decay_factor = 1.0 / np.max(distances)
    heuristic = np.zeros_like(distances)
    for i in range(distances.shape[0]):
        for j in range(distances.shape[1]):
            if i != j:
                heuristic[i, j] = (1.0 / distances[i, j]) * (1 + decay_factor * np.mean(distances[i]))
    pheromone = np.sum(1.0 / distances, axis=1, keepdims=True) / (np.count_nonzero(distances > 0, axis=1, keepdims=True) + 1e-10)
